/** The width of `text` in em; a character without a known width counts as `fallbackEm`. */
export function textWidthEm(text: string, advances: Readonly<Record<string, number>> = PLEX_SEMIBOLD_ADVANCE, fallbackEm = 0.6): number {
  let width = 0;
  for (const ch of text) width += advances[ch] ?? fallbackEm;
  return width;
}
